"""Jalur Next.js (mengikuti topik roadmap.sh/nextjs). Contoh memakai Next.js 15 App Router."""
from rb_lib import C, M, q, X


def T(soal, petunjuk, jawab):
    return X(soal, petunjuk, jawab, 'tsx')


