    "// app/produk/[slug]/page.tsx\nimport { notFound } from 'next/navigation';\nimport { ambilProduk, semuaSlug } from '@/lib/produk';\n\nexport async function generateStaticParams() {\n  return (await semuaSlug()).map((slug) => ({ slug }));\n}\n\nexport async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {\n  const p = await ambilProduk((await params).slug);\n  return { title: p ? `${p.nama} | Tokoku` : 'Tidak ditemukan' };\n}\n\nexport default async function DetailProduk({ params }: { params: Promise<{ slug: string }> }) {\n  const { slug } = await params;\n  const p = await ambilProduk(slug);\n  if (!p) notFound();\n  return (\n    <main className=\"p-4\">\n      <h1 className=\"text-2xl font-bold\">{p.nama}</h1>\n      <p>Rp{p.harga.toLocaleString('id-ID')}</p>\n    </main>\n  );\n}",
    None, 'tsx',
    pts=['[slug] = segmen dinamis.', 'params di-await di Next.js 15.', 'generateStaticParams dan generateMetadata.'],
